{
  "case_id": "C02",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "What senescent cells are",
      "narration": "As we age, some cells enter a stable growth arrest but keep secreting signals - cells that won't retire, and won't stop shouting at their neighbours. These senescent cells accumulate with age in several tissues, and in rodents, targeted removal has been reported to improve healthspan measures.",
      "on_screen": "Animation of dividing cells; one halts and emits signal molecules. Caption: senescent cells - stable growth arrest plus secretory phenotype. Footer: reported in rodents.",
      "claim_refs": ["CL01", "CL02"]
    },
    {
      "beat": "The mouse study",
      "narration": "In a randomised preclinical study, 96 aged mice - 24-month-old male and female C57BL/6J, 48 per sex - received the senolytic combination dasatinib and quercetin, or vehicle, by oral gavage on 3 consecutive days every 14 days for 16 weeks.",
      "on_screen": "Study card: 96 mice, 24 months old, C57BL/6J, 48 per sex; two arms, D+Q vs vehicle; dosing 3 consecutive days every 14 days, 16 weeks. Note: randomised by cage, not by animal.",
      "claim_refs": ["CL03", "CL04"]
    },
    {
      "beat": "What was measured",
      "narration": "In these mice, p16INK4a-positive cell burden in inguinal adipose tissue was 41% lower than vehicle, p less than 0.001, and rotarod latency was 22% better, p equals 0.004 - both two-sided t-tests with Holm correction across four pre-specified measures. Median remaining lifespan from the start of treatment was 26.9 weeks in treated animals versus 21.4 weeks in vehicle, log-rank p equals 0.01.",
      "on_screen": "Three result rows, each labelled 'in mice': -41% p16INK4a-positive burden, inguinal adipose only (p<0.001); +22% rotarod latency (p=0.004); median remaining lifespan 26.9 vs 21.4 weeks (log-rank p=0.01). Sidebar: two-sided t-tests, Holm correction; separate endpoints, not a demonstrated mechanism.",
      "claim_refs": ["CL05", "CL06", "CL07"]
    },
    {
      "beat": "What it does not show",
      "narration": "Grip strength showed no detected difference, p equals 0.62, and the study was not powered for it. One inbred strain, one age, adipose tissue only, and mice only - no human results here.",
      "on_screen": "Limits card: grip strength p=0.62 - no difference detected, not proof of no effect; powered for p16INK4a burden (30% difference, 80% power); C57BL/6J at 24 months; inguinal adipose only; preclinical, no human participants.",
      "claim_refs": ["CL08", "CL04", "CL05"]
    }
  ]
}

